#!/usr/bin/env node
/**
 * Build a memory-resident text-file index for search/warm-cache purposes.
 *
 * Default scope is the current project root. To request a full-system scan,
 * run with OPENCLAW_INDEX_SCOPE=/ . This is intentionally explicit because
 * scanning the whole machine from a Git hook can be expensive and sensitive.
 *
 * Output: a compact JSON summary at .cache/openclaw-index/latest.json.
 * The index itself is held in memory while the process runs; the summary is
 * persisted only for observability/debugging.
 */
import { createHash } from 'node:crypto';
import { createReadStream, promises as fs } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const projectRoot = path.resolve(scriptDir, '..');
const scope = path.resolve(process.env.OPENCLAW_INDEX_SCOPE || projectRoot);
const maxBytes = Number.parseInt(process.env.OPENCLAW_INDEX_MAX_BYTES || `${2 * 1024 * 1024}`, 10);
const maxFiles = Number.parseInt(process.env.OPENCLAW_INDEX_MAX_FILES || '50000', 10);
const startedAt = new Date();

const skipNames = new Set([
  '.git', 'node_modules', '.cache', '.next', 'dist', 'build', 'coverage',
  'vendor', '__pycache__', '.venv', 'venv', 'tmp', 'temp'
]);

const skipAbsPrefixes = [
  '/proc', '/sys', '/dev', '/run', '/mnt', '/media', '/lost+found',
  '/var/lib/docker', '/var/lib/containerd', '/var/cache', '/var/tmp',
  '/tmp', '/root/.ssh', '/home/.ssh'
];

const textExts = new Set([
  '.txt', '.md', '.markdown', '.rst', '.adoc', '.csv', '.tsv', '.json', '.jsonl',
  '.yaml', '.yml', '.toml', '.ini', '.conf', '.config', '.env', '.example',
  '.js', '.mjs', '.cjs', '.ts', '.tsx', '.jsx', '.py', '.rb', '.go', '.rs',
  '.java', '.kt', '.kts', '.c', '.h', '.cc', '.cpp', '.hpp', '.cs', '.php',
  '.sh', '.bash', '.zsh', '.fish', '.ps1', '.sql', '.html', '.htm', '.css',
  '.scss', '.xml', '.svg', '.gitignore', '.dockerignore', '.editorconfig'
]);

// Memory-resident index: path -> metadata + tokens while process is alive.
const memoryIndex = new Map();
let scanned = 0;
let indexed = 0;
let skipped = 0;
let errors = 0;

function shouldSkipDir(absPath, name) {
  if (skipNames.has(name)) return true;
  if (scope === '/' && skipAbsPrefixes.some((prefix) => absPath === prefix || absPath.startsWith(prefix + '/'))) return true;
  return false;
}

function looksTextPath(file) {
  const base = path.basename(file).toLowerCase();
  if (textExts.has(base)) return true;
  return textExts.has(path.extname(base));
}

function tokenize(text) {
  const counts = new Map();
  const words = text.toLowerCase().match(/[a-z0-9_][a-z0-9_./:-]{1,63}/g) || [];
  for (const word of words) counts.set(word, (counts.get(word) || 0) + 1);
  return Object.fromEntries([...counts.entries()].slice(0, 5000));
}

async function readSmallText(file, size) {
  const chunks = [];
  let seen = 0;
  for await (const chunk of createReadStream(file, { highWaterMark: 64 * 1024 })) {
    chunks.push(chunk);
    seen += chunk.length;
    if (seen >= size) break;
  }
  const buf = Buffer.concat(chunks, Math.min(seen, size));
  if (buf.includes(0)) return null;
  return buf.toString('utf8');
}

async function indexFile(file, stat) {
  scanned++;
  if (indexed >= maxFiles) return;
  if (stat.size > maxBytes || !looksTextPath(file)) {
    skipped++;
    return;
  }
  const text = await readSmallText(file, stat.size);
  if (text == null) {
    skipped++;
    return;
  }
  const hash = createHash('sha256').update(text).digest('hex');
  memoryIndex.set(file, {
    bytes: stat.size,
    mtimeMs: stat.mtimeMs,
    sha256: hash,
    tokens: tokenize(text)
  });
  indexed++;
}

async function walk(dir) {
  let entries;
  try {
    entries = await fs.readdir(dir, { withFileTypes: true });
  } catch {
    errors++;
    return;
  }

  for (const entry of entries) {
    if (indexed >= maxFiles) return;
    const abs = path.join(dir, entry.name);
    try {
      if (entry.isSymbolicLink()) {
        skipped++;
      } else if (entry.isDirectory()) {
        if (shouldSkipDir(abs, entry.name)) skipped++;
        else await walk(abs);
      } else if (entry.isFile()) {
        const stat = await fs.stat(abs);
        await indexFile(abs, stat);
      }
    } catch {
      errors++;
    }
  }
}

await walk(scope);

const outDir = path.join(projectRoot, '.cache', 'openclaw-index');
await fs.mkdir(outDir, { recursive: true });
const summary = {
  startedAt: startedAt.toISOString(),
  finishedAt: new Date().toISOString(),
  scope,
  fullSystemScan: scope === '/',
  scanned,
  indexed,
  skipped,
  errors,
  maxBytes,
  maxFiles,
  residentEntriesBuilt: memoryIndex.size,
  note: 'The detailed index is memory-resident during this run; only this summary is persisted.'
};
await fs.writeFile(path.join(outDir, 'latest.json'), JSON.stringify(summary, null, 2) + '\n');
console.log(JSON.stringify(summary));
EOF
chmod +x scripts/text-indexer.mjs

cat > .git/hooks/post-merge <<'EOF'
#!/bin/sh
# Launch the text indexer after successful merges without blocking Git.
# Set OPENCLAW_INDEX_SCOPE=/ to request an explicit full-system scan.

repo_root="$(git rev-parse --show-toplevel 2>/dev/null)" || exit 0
indexer="$repo_root/scripts/text-indexer.mjs"
log_dir="$repo_root/.cache/openclaw-index"
log_file="$log_dir/post-merge.log"

[ -x "$indexer" ] || exit 0
mkdir -p "$log_dir"

(
  cd "$repo_root" || exit 0
  nohup "$indexer" >>"$log_file" 2>&1 &
) >/dev/null 2>&1

exit 0
EOF
chmod +x .git/hooks/post-merge

git status --short
printf '\npost-merge hook:\n'; sed -n '1,80p' .git/hooks/post-merge
printf '\nindexer head:\n'; sed -n '1,80p' scripts/text-indexer.mjs

